recipes.code:
{
  "inputs": [
    {
      "id": "laddro-api-key",
      "type": "promptString",
      "description": "Your Laddro Career API key from console.laddro.com",
      "password": true
    }
  ],
  "servers": {
    "career": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@laddro/career-mcp@0.4.0"
      ],
      "env": {
        "LADDRO_API_KEY": "${input:laddro-api-key}"
      }
    }
  }
}
